import{_ as n,C as o,o as t,c as d,a2 as a,b as r,w as s,a as h,E as l,a3 as p}from"./chunks/framework.Dg5fKO7V.js";const v=JSON.parse('{"title":"Development Setup","description":"","frontmatter":{},"headers":[],"relativePath":"Development-Setup.md","filePath":"Development-Setup.md","lastUpdated":1788563284000}'),c={name:"Development-Setup.md"};function u(g,e,b,k,m,y){const i=o("Mermaid");return t(),d("div",null,[e[1]||(e[1]=a(`<h1 id="development-setup" tabindex="-1">Development Setup <a class="header-anchor" href="#development-setup" aria-label="Permalink to &quot;Development Setup&quot;">​</a></h1><p>Everything below assumes you have cloned the repository and are sitting in its root.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/xeidral/anisphere</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> anisphere</span></span></code></pre></div><h2 id="what-you-need-installed" tabindex="-1">What you need installed <a class="header-anchor" href="#what-you-need-installed" aria-label="Permalink to &quot;What you need installed&quot;">​</a></h2><p><strong>Node.js 20 or newer.</strong> Check with <code>node --version</code>.</p><p><strong>Rust, stable channel,</strong> through <a href="https://rustup.rs" target="_blank" rel="noreferrer">rustup</a>. The default toolchain already carries <code>rustfmt</code> and Clippy, so <code>rustup default stable</code> is the whole setup. Check with <code>cargo --version</code>.</p><p><strong>Your platform&#39;s Tauri dependencies.</strong> The <a href="https://tauri.app/start/prerequisites/" target="_blank" rel="noreferrer">Tauri prerequisites guide</a> is the authority, and the short version is:</p><table tabindex="0"><thead><tr><th>Platform</th><th>What is missing on a fresh machine</th></tr></thead><tbody><tr><td>Windows</td><td>Microsoft C++ Build Tools, and the WebView2 runtime that Windows 11 already ships</td></tr><tr><td>macOS</td><td>The Xcode command line tools, <code>xcode-select --install</code></td></tr><tr><td>Linux</td><td><code>webkit2gtk</code>, <code>libappindicator</code>, <code>librsvg</code> and the usual build essentials</td></tr></tbody></table><h2 id="prepare-the-checkout" tabindex="-1">Prepare the checkout <a class="header-anchor" href="#prepare-the-checkout" aria-label="Permalink to &quot;Prepare the checkout&quot;">​</a></h2><p>There is no setup script. Install the repository dependencies with the package and Rust tools directly:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rustup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> component</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rustfmt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clippy</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fetch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --manifest-path</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src-tauri/Cargo.toml</span></span></code></pre></div><p><code>npm ci</code> uses the committed lockfile and leaves <code>node_modules</code> ready for the application scripts. If Windows reports a locked file, stop every running dev server or AniSphere process and run it again.</p><p>Copy the public build-time values into a local environment file:</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-AFbbE" id="tab-ofqjGJr" checked><label data-title="macOS and Linux" for="tab-ofqjGJr">macOS and Linux</label><input type="radio" name="group-AFbbE" id="tab-u1zahz0"><label data-title="PowerShell" for="tab-u1zahz0">PowerShell</label></div><div class="blocks"><div class="language-bash vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span></code></pre></div><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Copy-Item</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> .env.example .env</span></span></code></pre></div></div></div><h2 id="first-run" tabindex="-1">First run <a class="header-anchor" href="#first-run" aria-label="Permalink to &quot;First run&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tauri:dev</span></span></code></pre></div><p>The first <code>tauri:dev</code> compiles the Rust side, which takes a few minutes on a cold machine and seconds after that.</p><p>The first launch also downloads the catalogue, a little over twenty thousand titles from <a href="https://github.com/manami-project/anime-offline-database" target="_blank" rel="noreferrer">manami-project</a>, and writes them into a local SQLite file. That happens once. Every later start reads from disk.</p><h2 id="what-npm-run-tauri-dev-actually-does" tabindex="-1">What <code>npm run tauri:dev</code> actually does <a class="header-anchor" href="#what-npm-run-tauri-dev-actually-does" aria-label="Permalink to &quot;What \`npm run tauri:dev\` actually does&quot;">​</a></h2><p>Four things, in order:</p><ol><li>Loads <code>.env</code> if there is one. A variable already set in your shell wins over the file.</li><li>Runs the test gate. Only the side you edited runs, so a second start in a row is instant.</li><li>Starts Vite on port 1420 with hot reload for the interface.</li><li>Builds and launches the native window against that dev server.</li></ol><p>Edit anything under <code>src/</code> and the window updates without restarting. Edit anything under <code>src-tauri/</code> and you stop and start again, because that half is compiled Rust.</p><h3 id="skipping-the-gate" tabindex="-1">Skipping the gate <a class="header-anchor" href="#skipping-the-gate" aria-label="Permalink to &quot;Skipping the gate&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tauri:dev</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-tests</span></span></code></pre></div><p>Also accepted as <code>--no-test</code>, or by setting <code>ANISPHERE_SKIP_TESTS=1</code>. Use it when you already know the suite is green and want the window up now.</p><p>The opposite exists too. <code>--all-tests</code> ignores the change detection and runs both suites whatever the tree looks like.</p><table tabindex="0"><thead><tr><th>Command</th><th>Runs</th></tr></thead><tbody><tr><td><code>npm run tauri:dev</code></td><td>Only the side you edited since the last green run</td></tr><tr><td><code>npm run tauri:dev -- --no-tests</code></td><td>Nothing, straight to the window</td></tr><tr><td><code>npm run tauri:dev -- --all-tests</code></td><td>Frontend and Rust every time</td></tr></tbody></table><p>The <code>--</code> matters. It tells npm the flag belongs to the script rather than to npm itself.</p><p>The change detection fingerprints <code>src/</code>, <code>scripts/</code>, the Vite and TypeScript configuration and the package lock separately from <code>src-tauri/src/</code> and the Rust manifests. It stores the last green values under <code>node_modules/.cache/anisphere/</code>. A side is recorded only after it has passed, so a red suite is never skipped on the next start. Delete that folder to force a full run.</p><h3 id="interface-work-without-the-native-shell" tabindex="-1">Interface work without the native shell <a class="header-anchor" href="#interface-work-without-the-native-shell" aria-label="Permalink to &quot;Interface work without the native shell&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>Vite alone, in your browser, on <code>http://localhost:1420</code>. Every backend call fails there because no Tauri runtime sits behind it, so this is useful for pure layout and styling and nothing else.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>Copy <code>.env.example</code> to <code>.env</code>. Every value in that file is already filled in and every one of them is public, because they all ship inside the released binary anyway. There is nothing to request and nothing to keep secret.</p><table tabindex="0"><thead><tr><th>Value</th><th>Read at</th><th>Purpose</th></tr></thead><tbody><tr><td><code>ANISPHERE_ANILIST_CLIENT_ID</code></td><td>compile time</td><td>The AniList application the login points at</td></tr><tr><td><code>ANISPHERE_DISCORD_APP_ID</code></td><td>compile time</td><td>The Discord application the presence is published under</td></tr><tr><td><code>ANISPHERE_DISCORD_IMAGE</code></td><td>compile time</td><td>Publicly reachable image used as the presence badge</td></tr><tr><td><code>ANISPHERE_UPDATER_ENDPOINT</code></td><td>bundle time</td><td>HTTPS URL of the update manifest</td></tr><tr><td><code>ANISPHERE_UPDATER_PUBKEY</code></td><td>bundle time</td><td>Public key that verifies update signatures</td></tr></tbody></table><p>Leave any of them blank and the matching feature switches off. Blank the AniList id and the login button disappears, blank both updater values and the app stops checking for updates. Nothing else changes.</p><p>The AniList login uses the implicit grant, the OAuth flow meant for clients that cannot keep a secret. A desktop binary is exactly that, so no client secret exists anywhere in this repository. See <a href="./Data-Privacy-And-Security">Data, Privacy and Security</a>.</p><h2 id="debugging-in-vs-code" tabindex="-1">Debugging in VS Code <a class="header-anchor" href="#debugging-in-vs-code" aria-label="Permalink to &quot;Debugging in VS Code&quot;">​</a></h2><p>The repository carries a working debug setup for both halves of the app at once: breakpoints in Rust and breakpoints in TypeScript, in one session, from one keypress.</p><p>A checkout already has it in <code>.vscode/</code>. To drop it into another one, these are the two files:</p><div class="download-row"><a class="download-card" href="/vscode/launch.json" download><span class="download-name">launch.json</span><span class="download-hint">the three debug configurations</span></a><a class="download-card" href="/vscode/tasks.json" download><span class="download-name">tasks.json</span><span class="download-hint">the build steps they depend on</span></a></div><p>Both go in a <code>.vscode/</code> folder at the root of the checkout.</p><h3 id="extensions" tabindex="-1">Extensions <a class="header-anchor" href="#extensions" aria-label="Permalink to &quot;Extensions&quot;">​</a></h3><p>Two, and the debugger does not start without them. Install them from VS Code&#39;s extension view:</p><ul><li><a href="https://marketplace.visualstudio.com/items?itemName=rust-lang.rust-analyzer" target="_blank" rel="noreferrer">rust-analyzer</a></li><li><a href="https://marketplace.visualstudio.com/items?itemName=ms-vscode.cpptools" target="_blank" rel="noreferrer">C/C++</a> on Windows, for the <code>cppvsdbg</code> debug type. On macOS and Linux install <a href="https://marketplace.visualstudio.com/items?itemName=vadimcn.vscode-lldb" target="_blank" rel="noreferrer">CodeLLDB</a> instead and change the <code>type</code> of the Rust configuration to <code>lldb</code>.</li></ul><h3 id="the-three-configurations" tabindex="-1">The three configurations <a class="header-anchor" href="#the-three-configurations" aria-label="Permalink to &quot;The three configurations&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Debug AniSphere (Rust + UI)</strong></td><td>The one you press F5 on. A compound that starts the other two together.</td></tr><tr><td>Rust backend</td><td>Launches the debug binary with <code>RUST_LOG=info,anisphere_lib=debug</code> and opens the WebView2 remote debugging port.</td></tr><tr><td>WebView frontend</td><td>Attaches to that port so TypeScript breakpoints bind.</td></tr></tbody></table><p>The two halves are marked hidden. Running either alone gives you half a debugger, so only the compound appears in the dropdown.</p><h3 id="pressing-f5" tabindex="-1">Pressing F5 <a class="header-anchor" href="#pressing-f5" aria-label="Permalink to &quot;Pressing F5&quot;">​</a></h3>`,49)),(t(),r(p,null,{default:s(()=>[l(i,{id:"mermaid-338",class:"mermaid",graph:"flowchart%20LR%0A%20%20prep%5B%22tauri%3Adebug%3Aprep%22%5D%20--%3E%20vite%5B%22vite%20on%20%3A1420%22%5D%0A%20%20vite%20--%3E%20build%5B%22cargo%20build%22%5D%0A%20%20build%20--%3E%20launch%5B%22launch%20anisphere.exe%22%5D%0A%20%20launch%20--%3E%20attach%5B%22attach%20to%20%3A9222%22%5D%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[h(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<p>The <code>tauri:debug:prep</code> task runs first. It brings Vite up and waits for it to report ready, then builds the Rust binary. Once that finishes VS Code launches the binary and attaches the WebView debugger.</p><p>A cold <code>cargo build</code> takes a few minutes. The attach timeout allows two of them for that reason, and if you still time out, run <code>cargo build --manifest-path src-tauri/Cargo.toml</code> once by hand and press F5 again.</p><p>Then set breakpoints anywhere. One in <code>src-tauri/src/commands/</code> and one in the <code>src/features/</code> code that calls it both bind in the same session, so you can step across the IPC boundary in a single run.</p><h3 id="debugging-one-test" tabindex="-1">Debugging one test <a class="header-anchor" href="#debugging-one-test" aria-label="Permalink to &quot;Debugging one test&quot;">​</a></h3><p>The third configuration, <strong>Vitest: current file</strong>, runs whichever file is focused in the editor under the debugger. Open a test, set a breakpoint, pick it from the dropdown.</p><p>For Rust, rust-analyzer puts a <code>Debug</code> lens directly above every <code>#[test]</code> function. Click it.</p><h3 id="reading-logs-instead" tabindex="-1">Reading logs instead <a class="header-anchor" href="#reading-logs-instead" aria-label="Permalink to &quot;Reading logs instead&quot;">​</a></h3><p>The backend writes to stdout, so a plain <code>npm run tauri:dev</code> shows it in the terminal. Turn the volume up with <code>RUST_LOG</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">RUST_LOG</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">debug</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tauri:dev</span></span></code></pre></div><p>On PowerShell that is <code>$env:RUST_LOG = &quot;debug&quot;</code> on a line of its own first.</p><p>Frontend logs go to the WebView console. Right click inside the window and choose Inspect, or press F12 in a debug build.</p><h2 id="before-you-open-a-pull-request" tabindex="-1">Before you open a pull request <a class="header-anchor" href="#before-you-open-a-pull-request" aria-label="Permalink to &quot;Before you open a pull request&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci:local</span></span></code></pre></div><p>Ten steps in the order CI runs them, stopping at the first failure: the tooling contracts, TypeScript, Prettier, ESLint at zero warnings, Knip for unused code, the frontend suite, the frontend build, <code>cargo fmt --check</code>, the offline Rust suite, and Clippy at <code>-D warnings</code>.</p><p>Green here is green on CI. <a href="./Testing">Testing</a> covers the individual layers and <a href="./Coding-Standards">Coding Standards</a> covers what a review looks at.</p><h2 id="building-installers" tabindex="-1">Building installers <a class="header-anchor" href="#building-installers" aria-label="Permalink to &quot;Building installers&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tauri:build</span></span></code></pre></div><p>An NSIS installer and an MSI on Windows, a <code>.dmg</code> and an <code>.app</code> on macOS, a <code>.deb</code> and an <code>.AppImage</code> on Linux. Output lands in <code>src-tauri/target/release/bundle/</code>.</p><table tabindex="0"><thead><tr><th>Goal</th><th>Command</th></tr></thead><tbody><tr><td>Hot reload while working</td><td><code>npm run tauri:dev</code></td></tr><tr><td>Debug bundle with symbols kept</td><td><code>npm run tauri:build -- --debug</code></td></tr><tr><td>Release bundle</td><td><code>npm run tauri:build</code></td></tr></tbody></table><p>The release profile aborts on panic, uses link-time optimization and a single codegen unit, builds for size and strips symbols. That combination is what keeps the binary small, and it is also why the first release build is slow. <a href="./Build-Notes">Build Notes</a> has the numbers.</p>',20))])}const F=n(c,[["render",u]]);export{v as __pageData,F as default};
